'use client';

/**
 * A code block that shows the same snippet as JS (generated by stripping the
 * types) and TS (as authored), JS open by default and TS one click away. The
 * JavaScript is never hand-written — it comes from the TypeScript source via
 * src/lib/coding/to-js.ts, so the two can't drift.
 *
 * When the snippet is not TypeScript, or stripping the types changes nothing
 * (it is already plain JS), it renders a single code block with no tabs.
 *
 * Reusable on its own: pass a TS `code` string and, optionally, the fence
 * `lang`. The lesson view loads it lazily (code-tabs-lazy.tsx). The feed's code
 * card draws the same two variants in its editor window (use-code-variants.ts)
 * and shares the remembered choice (code-tabs-pref.ts).
 *
 * Accessible as an ARIA tablist: Left/Right/Home/End move between tabs, the
 * panel is labelled by its tab, and the chosen variant is remembered for the
 * session so a reader who prefers one keeps it across blocks.
 */

import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { codeTabsModel } from '@/lib/coding/code-tabs-model';
import { readCodeVariantPref, writeCodeVariantPref, type CodeVariant } from '@/lib/coding/code-tabs-pref';
import { CODE_BLOCK_CLASS } from './code-block';

type Variant = CodeVariant;
const ORDER: Variant[] = ['js', 'ts'];
const LABEL: Record<Variant, string> = { js: 'JS', ts: 'TS' };

export default function CodeTabs({ code, lang }: { code: string; lang?: string }) {
  const model = codeTabsModel(code, lang);
  const baseId = useId();
  // Start on JS (the default) for a stable first render; adopt the session
  // preference after mount to avoid a hydration mismatch.
  const [active, setActive] = useState<Variant>('js');
  const tabsRef = useRef<Array<HTMLButtonElement | null>>([]);

  useEffect(() => {
    if (model.tabs) setActive(readCodeVariantPref());
  }, [model.tabs]);

  const select = useCallback((v: Variant) => {
    setActive(v);
    writeCodeVariantPref(v);
  }, []);

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const i = ORDER.indexOf(active);
      let next = i;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = (i + 1) % ORDER.length;
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = (i - 1 + ORDER.length) % ORDER.length;
      else if (e.key === 'Home') next = 0;
      else if (e.key === 'End') next = ORDER.length - 1;
      else return;
      e.preventDefault();
      select(ORDER[next]);
      tabsRef.current[next]?.focus();
    },
    [active, select],
  );

  // Single block: not TypeScript, or nothing to strip.
  if (!model.tabs || model.js == null) {
    return <pre className={CODE_BLOCK_CLASS}>{model.ts}</pre>;
  }

  const shown = active === 'js' ? model.js : model.ts;

  return (
    <div className="mb-6" data-testid="code-tabs">
      <div role="tablist" aria-label="Variante del código" className="flex gap-1 border-b border-j-border">
        {ORDER.map((v, n) => {
          const selected = active === v;
          return (
            <button
              key={v}
              ref={(el) => {
                tabsRef.current[n] = el;
              }}
              type="button"
              role="tab"
              id={`${baseId}-tab-${v}`}
              aria-selected={selected}
              aria-controls={`${baseId}-panel`}
              tabIndex={selected ? 0 : -1}
              onClick={() => select(v)}
              onKeyDown={onKeyDown}
              className={
                'min-h-[32px] px-3 font-mono text-[10px] uppercase tracking-[0.15em] transition-colors ' +
                (selected
                  ? 'border-b-2 border-j-accent text-j-text'
                  : 'border-b-2 border-transparent text-j-text-tertiary hover:text-j-text')
              }
            >
              {LABEL[v]}
            </button>
          );
        })}
      </div>
      <div id={`${baseId}-panel`} role="tabpanel" aria-labelledby={`${baseId}-tab-${active}`}>
        <pre className={CODE_BLOCK_CLASS} lang="en">
          {shown}
        </pre>
      </div>
    </div>
  );
}
